struct loan { pool_t *pool; conn_t *conn; };
static void hand_back(struct loan *l) { pool_return(l->pool, l->conn); }

struct loan l = { pool, pool_checkout(pool, &err) };
if (!l.conn)
    return err;
__attribute__((cleanup(hand_back))) struct loan guard = l;
use(guard.conn);        /* every exit path returns the connection */
